import{_ as l,H as i,f as p,i as a}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"25 | 非结构化数据处理：大模型带来的增量能力","description":"","frontmatter":{},"headers":[{"level":2,"title":"非结构化数据的价值与传统挑战","slug":"非结构化数据的价值与传统挑战","link":"#非结构化数据的价值与传统挑战","children":[{"level":3,"title":"什么是非结构化数据","slug":"什么是非结构化数据","link":"#什么是非结构化数据","children":[]},{"level":3,"title":"非结构化数据的业务价值","slug":"非结构化数据的业务价值","link":"#非结构化数据的业务价值","children":[]},{"level":3,"title":"传统技术方案的局限","slug":"传统技术方案的局限","link":"#传统技术方案的局限","children":[]},{"level":3,"title":"大模型带来的能力突破","slug":"大模型带来的能力突破","link":"#大模型带来的能力突破","children":[]}]},{"level":2,"title":"技术架构设计","slug":"技术架构设计","link":"#技术架构设计","children":[{"level":3,"title":"整体架构","slug":"整体架构","link":"#整体架构","children":[]},{"level":3,"title":"关键技术决策","slug":"关键技术决策","link":"#关键技术决策","children":[]}]},{"level":2,"title":"成本、性能与质量","slug":"成本、性能与质量","link":"#成本、性能与质量","children":[{"level":3,"title":"成本优化策略","slug":"成本优化策略","link":"#成本优化策略","children":[]},{"level":3,"title":"性能优化策略","slug":"性能优化策略","link":"#性能优化策略","children":[]},{"level":3,"title":"质量保障","slug":"质量保障","link":"#质量保障","children":[]}]},{"level":2,"title":"数据安全与合规","slug":"数据安全与合规","link":"#数据安全与合规","children":[{"level":3,"title":"大模型备案问题","slug":"大模型备案问题","link":"#大模型备案问题","children":[]},{"level":3,"title":"模型记忆与训练数据泄露风险","slug":"模型记忆与训练数据泄露风险","link":"#模型记忆与训练数据泄露风险","children":[]},{"level":3,"title":"非结构化数据的脱敏","slug":"非结构化数据的脱敏","link":"#非结构化数据的脱敏","children":[]},{"level":3,"title":"多租户场景的提示词隔离","slug":"多租户场景的提示词隔离","link":"#多租户场景的提示词隔离","children":[]},{"level":3,"title":"特定场景的合规要点","slug":"特定场景的合规要点","link":"#特定场景的合规要点","children":[]}]},{"level":2,"title":"实践案例：神策企微客服服务群智能分析","slug":"实践案例-神策企微客服服务群智能分析","link":"#实践案例-神策企微客服服务群智能分析","children":[{"level":3,"title":"业务背景与目标","slug":"业务背景与目标","link":"#业务背景与目标","children":[]},{"level":3,"title":"技术实现方案","slug":"技术实现方案","link":"#技术实现方案","children":[]},{"level":3,"title":"应用价值与效果","slug":"应用价值与效果","link":"#应用价值与效果","children":[]}]},{"level":2,"title":"局限与展望","slug":"局限与展望","link":"#局限与展望","children":[]},{"level":2,"title":"课程总结","slug":"课程总结","link":"#课程总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"大数据应用实战/25｜非结构化数据处理：大模型带来的增量能力.md","filePath":"大数据应用实战/25｜非结构化数据处理：大模型带来的增量能力.md","lastUpdated":1795555553000}'),t={name:"大数据应用实战/25｜非结构化数据处理：大模型带来的增量能力.md"};function n(r,e,h,s,o,u){return i(),p("div",null,[...e[0]||(e[0]=[a('<h1 id="_25-非结构化数据处理-大模型带来的增量能力" tabindex="-1">25 | 非结构化数据处理：大模型带来的增量能力 <a class="header-anchor" href="#_25-非结构化数据处理-大模型带来的增量能力" aria-label="Permalink to &quot;25 | 非结构化数据处理：大模型带来的增量能力&quot;">​</a></h1><p>你好，我是曹犟。</p><p>在前面的课程中，我们讨论了典型的大数据应用。仔细回顾这些内容，会发现它们有一个共同特点，那就是主要处理的都是结构化数据。订单表、用户表、行为事件表，这些数据都有明确的 Schema，字段含义清晰。哪怕是日志，某种意义上因为语义固定，也可以划到结构化数据的范畴内。</p><p>但实际上，企业中 80% 的数据是非结构化的，而这些数据覆盖了企业业务的整个流程。传统的大数据系统对这些数据经常束手无策。你可能会说，我们可以用关键词匹配、用传统的NLP 技术等，但这些方法成本高、效果差、扩展性弱。而大模型的出现，带来了突破性的变化。</p><p>今天这节课，我们就来讨论大模型如何赋能非结构化数据处理，这是大模型给大数据领域带来的最重要的增量能力之一。</p><h2 id="非结构化数据的价值与传统挑战" tabindex="-1">非结构化数据的价值与传统挑战 <a class="header-anchor" href="#非结构化数据的价值与传统挑战" aria-label="Permalink to &quot;非结构化数据的价值与传统挑战&quot;">​</a></h2><h3 id="什么是非结构化数据" tabindex="-1">什么是非结构化数据 <a class="header-anchor" href="#什么是非结构化数据" aria-label="Permalink to &quot;什么是非结构化数据&quot;">​</a></h3><p>我们先来明确什么是非结构化数据。</p><p>从数据的组织方式来看，数据可以分为三类：</p><ul><li><p>结构化数据，有明确的 Schema，存储在关系数据库或数据仓库中，比如订单表、用户表。</p></li><li><p>半结构化数据，有一定的结构，但不够严格，比如 JSON、XML 等。</p></li><li><p>非结构化数据，没有预定义的数据模型，无法用表格来表示，比如文本、图片、音频、视频。</p></li></ul><p>企业中常见的非结构化数据类型很多。文本类数据包括客服对话、用户评论、问卷回答、合同文档、邮件、社交媒体内容。图像类数据包括产品图片、用户上传图片、营销素材。音频类数据包括客服录音、会议录音、语音留言。视频类数据包括产品宣传视频、直播内容、培训视频。</p><p>如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/25/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/25/1.png" alt=""></a></p><h3 id="非结构化数据的业务价值" tabindex="-1">非结构化数据的业务价值 <a class="header-anchor" href="#非结构化数据的业务价值" aria-label="Permalink to &quot;非结构化数据的业务价值&quot;">​</a></h3><p>这些非结构化数据，如果能够被有效处理，会带来巨大的业务价值。我们看几个具体的场景。</p><p>场景一：电商的用户评论分析</p><p>一个电商平台，每天会产生海量的用户评论，蕴含着大量有价值的信息，包括产品质量问题、功能需求、竞品对比、使用场景。</p><p>比如一条评论：“这个榨汁机用起来不错，就是声音有点大，比我之前用的九阳那款吵多了。不过清洗比较方便，这点我很满意。”</p><p>这条评论里包含了多少信息？第一，整体评价是正面的。第二，噪音是一个明确的问题点。第三，提到了竞品九阳，说明用户在做对比。第四，清洗方便是用户认可的卖点。第五，用户有使用多款榨汁机的经验，可能是这个品类的重度用户。</p><p>如果能自动提取这些信息，可以指导产品改进，在下一代产品中重点优化噪音问题；可以优化营销策略，在详情页突出“易清洗”这个卖点；可以做竞品分析，了解用户是怎么对比不同品牌的。</p><p>场景二：金融客服对话质检</p><p>一个银行的客服中心，每天有上万通电话，有很多关键信息可以提取：合规性、客户情绪、服务质量、业务机会。</p><p>我们需要检查，客服是否按照标准流程询问了客户身份？是否使用了禁用词汇？客户的情绪是满意还是不满？客服的回答是否专业？是否发现了交叉销售的机会？</p><p>如果能实现全量质检，就能发现系统性问题。比如发现某个时间段投诉率突然上升，可以及时介入调查；发现某个客服的服务质量持续偏低，可以针对性培训；发现客户频繁提到某个产品功能不好用，可以反馈给产品部门改进。</p><p>场景三：零售的商品图片理解一个电商平台，有数百万个商品，每个商品都有主图、详情图。传统做法是依赖商家手动打标签，成本高且标签体系受限。商家可能只会打“连衣裙”“夏季”这样的粗粒度标签。</p><p>但是从图片中，其实可以提取出更丰富的信息，品类、风格、颜色、材质、场景、适用人群。一张连衣裙的图片，可以识别出是法式复古风格，米白色，亚麻材质，适合度假场景，适合25-35 岁女性。</p><p>精准的商品理解可以优化搜索推荐。用户搜索“法式复古连衣裙”，就能精准召回。可以自动化商品管理，自动生成商品详情页的描述文案。可以做内容审核，识别违规图片。</p><p>场景四：内容平台的视频内容理解</p><p>一个短视频平台，每天有海量视频上传。传统做法是依赖创作者手动填写标题、标签、简介，准确性和完整性无法保证。很多创作者为了流量，会填写夸张的标题，或者打不相关的标签。</p><p>但是从视频中，可以自动提取出很多信息，视频主题、关键画面、情感基调、适合人群、精彩片段时间点。一个美食视频，可以识别出是川菜、麻辣口味、展示了烹饪过程、适合喜欢做菜的用户、最精彩的翻炒镜头在 1 分 23 秒。</p><p>精准的视频理解可以优化推荐算法，把内容推荐给真正感兴趣的用户。可以自动生成封面，选择最精彩的画面作为封面图。可以自动生成摘要，方便用户快速了解内容。可以提升内容分发效率，让好内容被更多人看到。</p><h3 id="传统技术方案的局限" tabindex="-1">传统技术方案的局限 <a class="header-anchor" href="#传统技术方案的局限" aria-label="Permalink to &quot;传统技术方案的局限&quot;">​</a></h3><p>那传统的技术方案能解决吗？我们来看看传统方案的局限。</p><ul><li><p>规则匹配，是最简单的方法。用关键词、正则表达式来提取信息。但覆盖率很低，语言表达千变万化，不可能穷举所有规则。维护成本很高，每次有新需求都要写新规则，规则之间还可能冲突。</p></li><li><p>传统 NLP，需要大量标注数据。你想做情感分析，就要标注几万条样本，标注成本很高。迁移性很差，在电商评论上训练的模型，换到金融客服场景就不行了。只能处理特定任务，</p></li><li><p>情感分析就是情感分析，不能顺便提取实体、识别意图。</p></li><li><p>传统 CV，同样需要大量标注。你想识别商品类目，就要标注几万张图片。泛化能力有限，标注的类目之外的商品就识别不了。</p></li><li><p>OCR，只能识别文字，无法理解语义。从一张发票上提取了“金额 1000 元”，但不知道这是什么类型的支出，不知道是否合理。</p></li><li><p>语音识别，只能转文字，无法理解内容。把一通客服电话转成了文字，但不知道客户的情绪，不知道问题有没有解决。</p></li></ul><p>传统方案的核心痛点，可以总结为后面这四点。</p><ul><li><p>处理成本高，需要大量人工标注和规则维护。</p></li><li><p>准确率受限，难以处理复杂语境和多样化表达。</p></li><li><p>扩展性差，新场景需要重新开发。</p></li><li><p>深度不足，只能做浅层处理，无法提取深层洞察。</p></li></ul><h3 id="大模型带来的能力突破" tabindex="-1">大模型带来的能力突破 <a class="header-anchor" href="#大模型带来的能力突破" aria-label="Permalink to &quot;大模型带来的能力突破&quot;">​</a></h3><p>大模型的出现，让非结构化数据处理发生了质的变化。</p><p>首先是强大的语义理解能力。</p><ul><li><p>多轮对话理解。在客服对话中，客户可能在第三轮才说出真正的诉求，前两轮都在铺垫。传统 NLP 只能看单轮，大模型可以理解整个对话的上下文。</p></li><li><p>隐含意图识别。客户说“你们这个产品怎么这么贵”，表面是在问价格，实际可能是在暗示希望有优惠。大模型可以识别出这种隐含意图。</p></li><li><p>情感与态度分析。不仅能识别正面、负面、中性，还能识别程度。“还可以”和“非常满意”都是正面，但程度不同。“有点失望”和“太糟糕了”都是负面，但强度不同。</p></li><li><p>跨语言理解。一个在中文语料上训练的大模型，也能处理英文、日文的文本，这种跨语言能力是传统 NLP 很难做到的。</p></li></ul><p>其次是知识整合与推理能力。</p><ul><li><p>结合常识进行推理。用户评论说“这个保温杯倒热水进去，十分钟就不热了”，大模型知道保温杯的作用就是保温，能推理出这是一个质量问题，而不仅仅是一个客观描述。</p></li><li><p>跨领域知识迁移。在电商评论中学到的情感分析能力，可以迁移到客服对话场景。在商品图片中学到的风格识别能力，可以迁移到服装搭配场景。</p></li><li><p>因果关系分析。用户说“上次买的榨汁机噪音太大，所以这次选了静音款”，大模型能识别出噪音大是原因，选静音款是结果。</p></li></ul><p>第三是多模态统一理解能力。传统方案中，文本、图像、音频是分开处理的。你要分别训练NLP 模型、CV 模型、语音模型。而多模态大模型，可以统一处理文本、图像、音频，还可以做到跨模态信息关联。一张商品图片上有文字“买二送一”，大模型既能识别图片中的商品，又能理解文字表达的促销信息，还能关联起来，知道这是一个促销商品。还可以分析视频中的对话。一个客服视频，大模型可以同时看画面和听声音，判断客服的表情、语气是否友好。</p><p>第四个核心能力则是零样本与少样本学习能力。无需标注数据即可完成任务。你想做情感分析，直接告诉大模型“请判断这段文本的情感”，不需要标注数据训练模型。通过少量示例快速适应新场景。如果零样本效果不够好，给几个例子，就能大幅提升效果。比如给 5 个评论样本，告诉大模型这是正面还是负面，它就能学会这个场景的情感判断。</p><p>这同时也大幅降低了使用门槛。以前要做一个情感分析系统，需要算法工程师标注数据、训练模型、调参优化，可能要几个月。现在产品经理写几行 Prompt，几分钟就能跑起来。</p><p>我们用一个表格来对比大模型方案和传统方案的差异。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/25/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/25/2.jpeg" alt=""></a></p><p>可以看到，大模型方案在易用性、泛化能力上有巨大优势，但在计算成本、可解释性上还有不足。在实际应用中，需要根据场景特点来选择。</p><p>基于这些核心能力，大模型在非结构化数据处理中可以完成很多任务，我用下图来表示这个典型价值链。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/25/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/25/3.png" alt=""></a></p><h2 id="技术架构设计" tabindex="-1">技术架构设计 <a class="header-anchor" href="#技术架构设计" aria-label="Permalink to &quot;技术架构设计&quot;">​</a></h2><p>理解了大模型的能力之后，我们来看看如何从零开始构建一个非结构化数据处理系统。</p><h3 id="整体架构" tabindex="-1">整体架构 <a class="header-anchor" href="#整体架构" aria-label="Permalink to &quot;整体架构&quot;">​</a></h3><p>一个典型的非结构化数据处理系统，可以分为六层架构，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/25/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/25/4.png" alt=""></a></p><p>数据源层，各类非结构化数据来源，包括业务系统产生的数据、用户生成的内容、第三方数据等。</p><p>数据采集层，采集非结构化数据。例如，对于客服对话，通过 API 实时采集。对于用户评论，通过爬虫或 API 批量采集。对于文件类数据，通过对象存储上传等。</p><p>数据存储层，通常可用对象存储（OSS/S3）存储原始文件，数据库存储元信息。比如一个视频文件存在 OSS，而视频的标题、时长、上传时间等元信息存在 MySQL。</p><p>大模型处理层，调用大模型 API 或部署私有化模型。这是整个系统的核心，负责对非结构化数据进行智能分析。</p><p>结果存储层，包含两类存储。一是结构化数据存储，大模型提取出的结构化信息，存储在Doris、ClickHouse 等 OLAP 数据库中，方便后续分析。二是向量数据库，存储文本、图片等内容的 Embedding 向量，用于语义检索、相似度匹配、内容去重等场景。常用的向量数据库包括 Milvus、Pinecone、Qdrant、Weaviate 等。</p><p>应用层，各类应用消费处理结果。BI 分析、智能推荐、自动化决策等应用，都可以使用处理后的结构化数据。</p><h3 id="关键技术决策" tabindex="-1">关键技术决策 <a class="header-anchor" href="#关键技术决策" aria-label="Permalink to &quot;关键技术决策&quot;">​</a></h3><p>在设计系统时，有几个关键的技术决策需要做出选择。</p><p>决策一：API 调用 vs 私有化部署</p><p>这是最重要的决策。使用大模型 API，还是自己部署模型？</p><p>这除了是一个技术决策之外，还需要充分考虑合规备案的问题。我的建议是，初期或数据不敏感的场景，优先使用 API，当然，海外市场和国内市场可选择的模型也不同。而数据敏感或要大规模应用时，可以考虑私有化部署开源模型。</p><p>决策二：实时处理 vs 批量处理</p><p>第二个决策是，数据要实时处理还是批量处理？</p><p>我的建议是，根据业务需求选择。</p><ul><li><p>实时处理，适合客服质检、内容审核等实时性要求高的场景。数据产生后立即处理，延迟在秒级。需要流式数据处理，成本相对较高，需要保持实时计算资源。</p></li><li><p>批量处理，适合评论分析、商品打标等对时效性要求不高的场景。数据产生后定时处理，延迟可以接受小时级甚至天级。可以使用批处理任务，晚上或者业务低峰期运行。成本相对较低，可以充分利用计算资源。</p></li></ul><p>决策三：同步调用 vs 异步处理</p><p>第三个决策是，调用大模型时是同步还是异步？</p><p>我的建议是，对于数据处理类的场景，应该优先使用异步处理。特别是对于批量数据处理，异步处理是必然选择。即使是单条数据处理，如果大模型响应时间超过 3 秒，也建议用异步方式，提升用户体验。</p><h2 id="成本、性能与质量" tabindex="-1">成本、性能与质量 <a class="header-anchor" href="#成本、性能与质量" aria-label="Permalink to &quot;成本、性能与质量&quot;">​</a></h2><p>在实际应用中，成本、性能和质量是三个非常重要的考量因素，也是我们在系统设计时需要重点考虑的。我总结了一些实践里的优化策略供你参考。</p><h3 id="成本优化策略" tabindex="-1">成本优化策略 <a class="header-anchor" href="#成本优化策略" aria-label="Permalink to &quot;成本优化策略&quot;">​</a></h3><p>策略一：选择合适的模型</p><p>并非所有数据都需要用最强大的模型。简单任务用小模型，复杂任务用大模型。比如，情感分析是相对简单的任务，可以用小模型，成本只有大模型的十分之一。而深度的意图识别、因果推理，需要用大模型。</p><p>对不同任务应该选择性价比最优的模型。国内模型通常比国外模型便宜。如果任务不需要最强的能力，选择性价比高的模型。</p><p>开源模型私有化部署适合大规模应用。如果每天要处理百万级数据，私有化部署开源模型，虽然初期投入高，但长期成本更低。</p><p>策略二：缓存机制与向量检索</p><p>相似内容的处理结果可以复用。使用 Embedding 相似度识别重复内容，如果相似度超过阈值，直接返回缓存结果。</p><p>这里就需要用到向量数据库。具体流程是，首先将新输入的内容转换为 Embedding 向量，然后在向量数据库中进行相似度检索，如果找到相似度很高的历史内容，直接返回之前的处理结果，无需再次调用大模型。如果没有找到相似内容，才调用大模型处理，并将结果和Embedding 存入向量数据库。</p><p>此外，向量数据库还可以用于构建 RAG（检索增强生成）系统。在调用大模型前，先从向量数据库中检索相关的历史对话、知识文档，作为上下文提供给大模型，可以提升回答的准确性和相关性。</p><p>策略三：批量处理</p><p>将多个任务合并到一次调用中。大模型 API 通常有 Token 上限，在不超过限制的前提下，可以把多条评论合并到一次调用中，“请分析以下 10 条评论的情感”。</p><p>批量处理可以降低 API 调用次数，因为很多 API 按次数收费或有 QPS 限制。但要注意单次调用的 Token 限制，不要超过上限。</p><p>策略四：输出长度控制</p><p>明确限制输出长度，避免生成冗余内容。“对话摘要不超过 30 字”，比让大模型自由发挥，可能节省 50% 的输出 Token。</p><p>按 Token 计费时，输出 Token 和输入 Token 通常是同价或输出更贵，所以控制输出长度，对成本影响很大。</p><h3 id="性能优化策略" tabindex="-1">性能优化策略 <a class="header-anchor" href="#性能优化策略" aria-label="Permalink to &quot;性能优化策略&quot;">​</a></h3><p>并发控制</p><p>API 有限流，需要控制并发。使用令牌桶或滑动窗口算法控制并发，避免触发限流。</p><p>失败自动重试，指数退避。如果请求失败，不要立即重试，而是等待一段时间再重试，等待时间指数增长，比如第一次等 1 秒，第二次等 2 秒，第三次等 4 秒。</p><p>异步处理</p><p>使用消息队列实现异步处理。避免同步等待造成的资源浪费。如果同步调用大模型，线程会一直等待，无法处理其他请求。异步处理可以释放线程，提升系统吞吐量。</p><p>结果缓存</p><p>相同输入的结果缓存。使用 Redis 等缓存中间件，把查询结果缓存起来，并且设置合理的过期时间。</p><h3 id="质量保障" tabindex="-1">质量保障 <a class="header-anchor" href="#质量保障" aria-label="Permalink to &quot;质量保障&quot;">​</a></h3><p>准确率评估</p><p>人工标注测试集，几百到几千条样本，覆盖各种场景。定期评估模型准确率，每周或每月评估一次，看是否有下降。不同任务建立不同的评估标准，情感分析看分类准确率，摘要生成看ROUGE 分数，信息提取看 F1 值。</p><p>Bad Case 分析</p><p>收集错误案例，哪些场景下大模型效果不好。分析错误原因，是 Prompt 不够清晰？是模型能力不足？还是数据质量有问题？针对性优化，调整 Prompt，更换模型，清洗数据。</p><p>人工校验机制关键业务保留人工审核。对于金融、医疗等高风险场景，即使有大模型，也要人工最终审核。置信度低的结果人工校验。大模型可以输出置信度分数，低于阈值的结果，人工复核。构建反馈闭环，将人工校验的结果，反馈给系统，用于持续优化 Prompt 和模型。</p><h2 id="数据安全与合规" tabindex="-1">数据安全与合规 <a class="header-anchor" href="#数据安全与合规" aria-label="Permalink to &quot;数据安全与合规&quot;">​</a></h2><p>与所有其他类型数据系统一样，大模型处理非结构化数据时数据安全和合规依然是重中之重。关于数据安全与合规的基础知识，我们在第 18 节课已经详细讨论过，这里只重点讨论大模型场景下的差异化问题。</p><h3 id="大模型备案问题" tabindex="-1">大模型备案问题 <a class="header-anchor" href="#大模型备案问题" aria-label="Permalink to &quot;大模型备案问题&quot;">​</a></h3><p>目前看，面向国内市场的应用、处理国内用户的数据，是不能使用未备案模型的，这一点是不容违反的红线。</p><h3 id="模型记忆与训练数据泄露风险" tabindex="-1">模型记忆与训练数据泄露风险 <a class="header-anchor" href="#模型记忆与训练数据泄露风险" aria-label="Permalink to &quot;模型记忆与训练数据泄露风险&quot;">​</a></h3><p>大模型在训练过程中可能记忆训练数据中的敏感信息。有研究发现，通过精心设计的Prompt，可以诱导模型输出训练数据中的隐私内容。虽然概率很低，但对于高敏感度数据，这仍然是需要警惕的风险。因此，对敏感数据，可能需要使用私有化部署的模型，确保数据不会被用于训练，从而降低泄露风险。</p><h3 id="非结构化数据的脱敏" tabindex="-1">非结构化数据的脱敏 <a class="header-anchor" href="#非结构化数据的脱敏" aria-label="Permalink to &quot;非结构化数据的脱敏&quot;">​</a></h3><p>非结构化数据比结构化数据更难识别敏感信息。比如在客服对话中，客户可能在自然对话中提到手机号、身份证号、家庭住址等。用户评论中可能包含个人经历、健康状况等隐私。这些信息分散在文本中，难以通过字段级别的权限控制来保护。</p><p>传统的脱敏方法是基于正则表达式识别敏感信息，但对于非结构化数据，可以使用更智能的方法。使用 NER（命名实体识别）模型或小型语言模型，识别文本中的人名、地名、组织名、电话号码、身份证号等敏感实体，将其替换为占位符后再发送给大模型。处理完成后，再将占位符还原为原始信息。</p><p>这种方法的优势是能够识别更复杂的敏感信息模式，比如“我家住在北京市朝阳区某某小区”这样的自然语言表达。</p><h3 id="多租户场景的提示词隔离" tabindex="-1">多租户场景的提示词隔离 <a class="header-anchor" href="#多租户场景的提示词隔离" aria-label="Permalink to &quot;多租户场景的提示词隔离&quot;">​</a></h3><p>在 SaaS 场景下，多个租户可能共享同一个大模型处理系统。需要确保不同租户的数据在Prompt 中完全隔离，不会相互泄露。技术上，每次调用大模型时，Prompt 中只能包含当前租户的数据，不能包含其他租户的历史对话或示例。在向量数据库中检索时，也必须加上租户ID 的过滤条件，避免跨租户检索。</p><h3 id="特定场景的合规要点" tabindex="-1">特定场景的合规要点 <a class="header-anchor" href="#特定场景的合规要点" aria-label="Permalink to &quot;特定场景的合规要点&quot;">​</a></h3><p>客服录音与对话分析的合规</p><p>在分析客服录音和对话时，必须事先获得用户同意。通话开始时，要明确告知“本次通话将被录音，用于质量监控和改进服务”，用户同意后才能录音和分析。分析结果的使用也要符合告知的目的，不能用于其他未经授权的用途。</p><p>UGC 内容的使用授权</p><p>对于用户评论、图片、视频等 UGC 内容，需要在用户协议中明确说明平台有权使用、分析这些内容。但要注意，即使用户同意，也不能将包含个人隐私的内容对外公开或用于训练公开模型。在使用大模型分析时，要确保分析结果是聚合的、去标识化的。</p><h2 id="实践案例-神策企微客服服务群智能分析" tabindex="-1">实践案例：神策企微客服服务群智能分析 <a class="header-anchor" href="#实践案例-神策企微客服服务群智能分析" aria-label="Permalink to &quot;实践案例：神策企微客服服务群智能分析&quot;">​</a></h2><p>现在我们通过一个实际案例，来看看如何在真实业务中落地。这是神策数据在企业微信客服服务群智能分析上的实践。</p><h3 id="业务背景与目标" tabindex="-1">业务背景与目标 <a class="header-anchor" href="#业务背景与目标" aria-label="Permalink to &quot;业务背景与目标&quot;">​</a></h3><p>神策是通过微信群为客户提供服务的，每天这些群里会产生大量对话，包括客户咨询产品功能、反馈使用问题、提出需求建议、对比竞品等，蕴含着大量有价值的信息。但之前由于群多、信息量大，是没有办法对这些信息进行有效的利用，只是安排了人工定期进行巡检，看看有没有问题遗漏。</p><p>最近，我们开始尝试用大模型来挖掘这些信息的价值，包括：</p><ul><li><p>从海量群聊对话中提取有价值的信息。群聊的特点是多人并行对话，话题切换频繁，单条消息信息量小，需要结合上下文理解。</p></li><li><p>识别客户的真实需求和痛点。客户不一定直接说“我需要什么”，可能是抱怨、暗示、对比，需要深入理解才能发现真实诉求。</p></li><li><p>发现产品问题和改进方向。客户反馈的问题，可能分散在不同的群、不同的时间，需要聚合分析才能发现系统性问题。</p></li><li><p>及时响应客户的紧急诉求。有些问题很紧急，比如系统故障、数据丢失，需要实时发现并告警。</p></li><li><p>评估客服人员的服务质量，包括响应是否及时，回答是否专业，态度是否友好等。</p></li></ul><h3 id="技术实现方案" tabindex="-1">技术实现方案 <a class="header-anchor" href="#技术实现方案" aria-label="Permalink to &quot;技术实现方案&quot;">​</a></h3><p>在数据采集方面，我们通过企业微信 API 实时采集服务群的对话消息，包括文本消息、图片、文件、@ 提及等。不同类型的消息需要分别处理，文本可以直接使用，图片需要 OCR，文件需要解析。采集时记录消息时间、发送者身份（客户 vs 客服）、上下文关系。需要知道每条消息的前后文，才能准确理解含义。</p><p>在数据 ETL 上，我们对数据按对话 session 进行分组。划分 session 时，单纯按时间窗口不够，我们尝试使用了 Embedding 相似度判断话题连续性，如果相邻消息的 Embedding 相似度高于阈值，就认为是同一个话题。</p><p>划分之后，我们会过滤无效消息，如表情包、纯图片、重复内容等，并且专门识别和处理了@ 提及、回复关系，也识别了图片中的文字信息。客户可能发截图反馈问题，需要提取图片中的文字，会转成文本后一起分析。</p><p>我们使用大模型对每个对话 session 进行多维度分析。</p><ul><li><p>对话摘要：总结这段对话的核心内容，提取关键实体，产品名称、功能模块、问题类型。</p></li><li><p>意图识别：客户的主要意图是什么，咨询、投诉、建议、闲聊？是否包含明确的需求或问题。</p></li><li><p>情感分析：客户满意、中性、不满？我们也做了情绪强度评分。</p></li><li><p>问题分类：客户提的问题是产品功能问题、性能问题、使用问题、定价问题？也对问题的紧急程度做了划分。</p></li><li><p>客服质量评估：响应及时性，客户提问后多久回复。回答专业性，回答是否准确、全面。服务态度，语气是否友好。问题解决情况，问题是否得到解决。</p></li></ul><p>处理之后的结构化结果存入 Doris。每个 session 的分析结果，包括摘要、意图、情感、问题等，都存储为一条记录，并与客户信息、产品使用数据进行关联，例如：产品版本、该版本对应的 Bug 列表、部署方式、历史使用数据等。</p><p>这些结构化数据可以用于构建多维分析看板，也可以提供自然语言检索。比如看最近一周客户投诉最多的问题是什么，哪些客户满意度最低，哪些客服的服务质量最好，也可以直接提问“哪些客户问到了数据接入类问题”。</p><p>整体处理流程如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/25/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/25/5.png" alt=""></a></p><h3 id="应用价值与效果" tabindex="-1">应用价值与效果 <a class="header-anchor" href="#应用价值与效果" aria-label="Permalink to &quot;应用价值与效果&quot;">​</a></h3><p>目前，这个系统已在日常工作中持续运行并迭代，有如下典型场景。</p><ul><li><p>客服质量提升：我们现在可以对客服进行全量质检，能够自动识别服务质量问题，并且为客服培训提供针对性案例。</p></li><li><p>产品改进：每周自动生成“客户反馈 Top 10 问题”报告，发给产品团队，为产品规划提供数据支持。产品规划不再拍脑袋，而是基于真实的客户反馈。</p></li><li><p>增购意向识别：通过对话识别客户是否有扩大使用规模，扩充功能模块的需求，并且自动记录下来，转给销售及时跟进。</p></li><li><p>竞品分析：从对话中了解客户为什么提到竞品，了解竞品的优势、劣势及与神策的差别是什么。</p></li></ul><h2 id="局限与展望" tabindex="-1">局限与展望 <a class="header-anchor" href="#局限与展望" aria-label="Permalink to &quot;局限与展望&quot;">​</a></h2><p>最后，我们来讨论用大模型处理非结构化数据的局限和未来的展望。</p><p>先说问题：</p><ul><li><p>成本：大模型处理成本相比传统方案显著更高，因此，大规模应用需要仔细评估 ROI，不是所有场景都适合。</p></li><li><p>准确率与幻觉：大模型仍然会出现错误和幻觉问题，可能编造不存在的信息。对于金融、医疗等高风险场景，必须保留人工审核环节。</p></li><li><p>可解释性不足：大模型是黑盒，难以解释为什么做出某个判断，出现错误时也难以定位原因。这在金融、医疗等监管严格的行业是个挑战。</p></li></ul><p>好消息是，这些局限正在快速改善。模型能力持续提升，多模态理解能力越来越强，上下文窗口越来越长。成本在竞争和技术优化的推动下持续下降，开源模型质量也在快速追赶闭源模型。应用场景会越来越丰富，从视频理解、实时音频理解，到更复杂的推理任务，大模型将在非结构化数据处理领域发挥越来越重要的作用。</p><h2 id="课程总结" tabindex="-1">课程总结 <a class="header-anchor" href="#课程总结" aria-label="Permalink to &quot;课程总结&quot;">​</a></h2><p>今天这节课，我们讨论了大模型如何赋能非结构化数据处理，整个系统应该如何设计，以及有哪些典型应用场景。</p><p>对于数据开发工程师，希望这节课能帮你掌握如何将大模型能力集成到大数据系统中，扩展系统处理的数据源，进一步发挥数据的价值。</p><p>对于数据产品经理，希望能帮你理解大模型的能力边界，识别用大模型处理非结构化数据能够解决哪些业务问题。</p><p>对于数据分析师，希望能帮你理解大模型如何将非结构化数据转化为可分析的结构化数据，从而扩展数据分析的边界。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ul><li><p>在你的业务中，有哪些非结构化数据目前还没有充分利用？能否用大模型来处理？</p></li><li><p>你觉得在你的场景中，使用大模型 API 还是私有化部署更合适？为什么？</p></li><li><p>你觉得引入了非结构化数据的处理能力之后，大数据系统的整体设计会有哪些变化？</p></li></ul><p>期待你在留言区分享你的思考，如果觉得内容对你有帮助，也欢迎你分享给其他人。下节课，我们将讨论 Data Agent，探讨大模型是否会颠覆传统的数据分析方式。</p>',153)])])}const E=l(t,[["render",n]]);export{c as __pageData,E as default};
